import numpy as np
# invalid input: a grid that is not divisible by four has no central block
def _probe(fn):
    try:
        fn(1.0,0.1,50)
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(_probe(dwlc_bond_energy), target)

